The complete graph \( y = g(x) \) consists of five line segments and is plotted below. What is the sum of the \( x \)-coordinates of all points where \( g(x) = 1.5 \)?

[asy]
size(150);
void rr_cartesian_axes(real xleft, real xright, real ybottom, real ytop, real xstep=1, real ystep=1, bool useticks=false, bool complexplane=false, bool usegrid=true) {
    import graph;
    real i;
    if(complexplane) {
        label("$\textnormal{Re}$",(xright,0),SE);
        label("$\textnormal{Im}$",(0,ytop),NW);
    } else {
        label("$x$",(xright+0.4,-0.5));
        label("$y$",(-0.5,ytop+0.2));
    }
    ylimits(ybottom,ytop);
    xlimits(xleft, xright);
    real[] TicksArrx,TicksArry;
    for(i=xleft+xstep; i<xright; i+=xstep) {
        if(abs(i) >0.1) {
            TicksArrx.push(i);
        }
    }
    for(i=ybottom+ystep; i<ytop; i+=ystep) {
        if(abs(i) >0.1) {
            TicksArry.push(i);
        }
    }
    if(usegrid) {
        xaxis(BottomTop(extend=false), Ticks("%", TicksArrx ,pTick=gray(0.22),extend=true),p=invisible);
        yaxis(LeftRight(extend=false),Ticks("%", TicksArry ,pTick=gray(0.22),extend=true), p=invisible);
    }
    if(useticks) {
        xequals(0, ymin=ybottom, ymax=ytop, p=black+0.8bp, Ticks("%",TicksArry , pTick=black+0.8bp), above=true, Arrows);
        yequals(0, xmin=xleft, xmax=xright, p=black+0.8bp, Ticks("%",TicksArrx , pTick=black+0.8bp), above=true, Arrows);
    } else {
        xequals(0, ymin=ybottom, ymax=ytop, p=black, above=true, Arrows);
        yequals(0, xmin=xleft, xmax=xright, p=black, above=true, Arrows);
